pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Put{value: 1.5 ether}(block.timestamp + 1);
        vm.warp(block.timestamp + 2);
        vm.prank(alice);
        c.Collect(0.5 ether);
        // Reference: Alice's balance after Collect is 1 ether (1.5 - 0.5 = 1)
        // Buggy version: same outcome here, but difference appears for another scenario
        // Actually, for a direct divergence, consider that MinSum = 1 ether.
        // Reference requires acc.balance >= MinSum (1 ether) for Collect to proceed.
        // After collecting 0.5, alice's balance = 1.0 ether, so Collect works.
        // Now test with a second user who has less than MinSum:
        address bob = address(0x5678);
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.Put{value: 0.5 ether}(block.timestamp + 1);
        vm.warp(block.timestamp + 2);
        // Bob tries to Collect(0.5 ether) with balance 0.5 ether < MinSum (1 ether)
        bool ok;
        try c.Collect(0.5 ether) { ok = true; } catch { ok = false; }
        // Reference reverts because balance (0.5) < MinSum (1), ok = false
        // Buggy version does not check MinSum, so it succeeds, ok = true
        assertTrue(ok == false, "Reference should revert, buggy version would not");
    }
}

