pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address user = address(0x1234);

    function setUp() public { 
        c = new C(address(this)); 
    }

    function testRegression_property() public {
        // Set block timestamp to 100
        vm.warp(100);

        // User deposits 1.5 ether with unlockTime 100 (but block.timestamp is 100, so unlockTime becomes block.timestamp = 100)
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.Put{value: 1.5 ether}(100);

        // Now warp past unlockTime (100) -> set timestamp to 200, but condition requires block.timestamp > acc.unlockTime = 100, so 200 > 100 is true for reference; we want a DIFFERENCE where reference reverts and mutant proceeds.
        // Actually, we need reference to FAIL the condition and mutant to PASS. condition is block.timestamp > acc.unlockTime.
        // If we warp to 100 (equal), reference condition fails (100 > 100 is false), reference reverts. Mutant without this condition will proceed.
        vm.warp(100); // block.timestamp == unlockTime, reference Collect will revert, mutant will succeed

        // Try Collect(1 ether) from user
        uint256 am = 1 ether;
        bool ok;
        vm.prank(user);
        // Use try-catch to capture revert
        try c.Collect{value: 0}(am) {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference (correct), Collect reverts because condition requires block.timestamp > acc.unlockTime, but 100 > 100 is false => revert => ok == false
        // In mutant (buggy), condition removed => Collect succeeds => ok == true
        // We assert that the reference behavior is ok == false
        assertTrue(!ok, "Reference should revert but did not");
    }
}

