        vm.prank(user);
        c.Put(50); // unlockTime = 50 (already passed), balance = 2 ether

        // Now call Collect(1.5 ether) as same user
        vm.prank(user);
        c.Collect(1.5 ether);

        // In reference: balance becomes 0.5 ether; in bug: balance stays 2 ether
        (uint256 unlockTime, uint256 balance) = c.Acc(user);
        assertTrue(balance == 0.5 ether, "Expected balance 0.5 ether after Collect");
    }
}

